#!/usr/bin/env node
import fs from "node:fs";
import { loadRegistry, Registry } from "../src/registry.js";
import { loadConfig } from "../src/config.js";
import { opencodeAuthSummary, discoverProviders, discoverModels, filterRegistryToCredentialed } from "../src/discover.js";
import { writeOpenCodeConfig, resolveConfigTarget, SCOPE_GLOBAL, SCOPE_PACKAGE, SCOPE_NONE } from "../src/opencode-config.js";
import { hasStoredCredentials, loadCredentials, switchrHome } from "../src/cli/credentials.js";
import { loadSettings, saveSettings } from "../src/cli/settings.js";
import { injectEnvCredentials } from "../src/cli/inject.js";
import { selectOne } from "../src/cli/prompts.js";
import { maskKey } from "../src/logger.js";

const HELP = `
switchr - OpenCode auto model switcher

USAGE:
  switchr setup                 auto-detect your OpenCode logins and write config
  switchr start                 ensure config, then run the proxy server on :8790
  switchr config                generate/refresh the OpenCode config (choose scope)
  switchr detect                show which providers/models are usable on this machine
  switchr models                list configured models
  switchr next                  force the running proxy to skip the current model on next request
  switchr file                  show where credentials are stored
  switchr help                  show this help

OPTIONS (apply to start/config):
  --scope global|package|none   where to write the OpenCode config
  --port <n>                    override port (default 8790)
  --host <h>                    override host (default 127.0.0.1)

NOTES:
  - No API key prompts: switchr reuses the credentials OpenCode itself is
    signed in with (auth.json) plus any *KEY* env vars already set.
  - Only models from providers you are actually logged into are registered.
  - Run \`switchr next\` in another terminal to force the proxy to switch models.
  - In \`switchr start\` (interactive TTY), press 'n' to force a model switch.

EXAMPLES:
  switchr setup                 auto-detect and configure
  switchr start                 start the proxy (asks config scope on first run)
  switchr start --scope package --port 9000
`;

function die(msg) {
  console.error(`error: ${msg}`);
  process.exit(1);
}

function printHeader() {
  console.log("\n\x1b[1mswitchr\x1b[0m - OpenCode auto model switcher\n");
}

const FORCE_NEXT_FILE = (() => {
  const home = switchrHome();
  fs.mkdirSync(home, { recursive: true });
  return `${home}\\force-next-model`;
})();

function triggerNextModel() {
  fs.writeFileSync(FORCE_NEXT_FILE, String(Date.now()), "utf8");
}

async function chooseScope(settings, flagScope) {
  if (flagScope) {
    if (![SCOPE_GLOBAL, SCOPE_PACKAGE, SCOPE_NONE].includes(flagScope)) die(`unknown scope "${flagScope}"`);
    return flagScope;
  }
  if (settings.scope) return settings.scope;
  const idx = await selectOne("Where should the OpenCode config be written?", [
    { label: "package  - .opencode/opencode.json in the current project (recommended)" },
    { label: "global   - ~/.config/opencode/opencode.json(c), all projects" },
    { label: "none     - do not write an OpenCode config" },
  ]);
  const scope = [SCOPE_PACKAGE, SCOPE_GLOBAL, SCOPE_NONE][idx];
  saveSettings({ scope });
  return scope;
}

/**
 * Build a registry restricted to providers the user can actually call. Falls
 * back to the full registry when nothing is credentialed (so `switchr models`
 * still shows what's available to configure).
 */
function credentialedRegistry(registry) {
  const availability = discoverProviders(registry);
  const usable = Object.values(availability).some((a) => a.available);
  if (!usable) return registry;
  const data = filterRegistryToCredentialed(registry, availability);
  return new Registry(data);
}

function printDiscovery(registry) {
  const availability = discoverProviders(registry);
  console.log("Providers discovered from your local OpenCode setup:\n");
  for (const [id, p] of Object.entries(registry.providers || {})) {
    const a = availability[id];
    const label = `${p.name || id}`;
    if (a?.available) console.log(`  \x1b[32m✓\x1b[0m ${label.padEnd(42)} ${a.source}`);
    else console.log(`  \x1b[90m✗\x1b[0m ${label.padEnd(42)} no credentials`);
  }
}

async function writeConfig({ scope, registry, config }) {
  const target = resolveConfigTarget(scope);
  if (!target) {
    console.log("skipped OpenCode config (scope=none)");
    return;
  }
  const { target: t, modelCount } = writeOpenCodeConfig({ target, config, registry });
  console.log(`\nwrote OpenCode config: ${t}`);
  console.log(`  registered ${modelCount} models under provider "modelswitcher"`);
  console.log('  in OpenCode run /models and pick "modelswitcher/auto".');
}

/** Return merged config with CLI overrides applied. */
function overrideConfig(overrides) {
  const base = loadConfig();
  if (overrides.port) base.port = Number(overrides.port) || base.port;
  if (overrides.host) base.host = overrides.host;
  return base;
}

function parseArgs(argv) {
  const opts = { _: [], scope: null, port: null, host: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--scope") opts.scope = argv[++i];
    else if (a === "--port") opts.port = argv[++i];
    else if (a === "--host") opts.host = argv[++i];
    else if (a === "--help" || a === "-h") opts._.push("help");
    else opts._.push(a);
  }
  return opts;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const nonFlag = args._.filter((x) => x && x !== "help");
  const command = (args._.includes("help") || !nonFlag.length) ? "help" : args._[0];
  const registry = loadRegistry();

  switch (command) {
    case "help":
      printHeader();
      console.log(HELP);
      break;

    case "setup": {
      printHeader();
      const config = overrideConfig(args);
      printDiscovery(registry);
      const credRegistry = credentialedRegistry(registry);
      if (credRegistry === registry) {
        console.log("\n\x1b[33mNo provider credentials found.\x1b[0m");
        console.log("  Log in to your providers in OpenCode first: run /connect in OpenCode,");
        console.log("  or set the matching *KEY* env vars (e.g. GEMINI_API_KEY), then re-run this.");
      }
      await writeConfig({ scope: await chooseScope(loadSettings(), args.scope), registry: credRegistry, config });
      console.log("\ndone. run `switchr start` to start the proxy.\n");
      break;
    }

    case "start": {
      printHeader();
      injectEnvCredentials(registry);
      const config = overrideConfig(args);
      const known = hasStoredCredentials();
      const anyEnvFilled = Object.values(registry.providers || {}).some((p) => {
        return (p.envKey || []).some((name) => process.env[name]);
      });
      if (!known && !anyEnvFilled) {
        console.log("no credentials found yet. Log in in OpenCode (/connect) or set *KEY* env vars,");
        console.log("or run `switchr setup` from a terminal.\n");
      }
      injectEnvCredentials(registry);
      const credRegistry = credentialedRegistry(registry);
      const availableModels = discoverModels(registry);
      if (!availableModels.length) {
        console.log("WARNING: no provider keys configured. The proxy will run but `auto` will fail all requests.");
      }
      const scope = await chooseScope(loadSettings(), args.scope);
      saveSettings({ scope });
      await writeConfig({ scope, registry: credRegistry, config });
      const host = config.host;
      const port = config.port;
      console.log(`\nstarting proxy on http://${host}:${port}  (Ctrl+C to stop)`);
      if (process.stdin.isTTY) {
        console.log("press 'n' to force model switch on next request\n");
        process.stdin.setRawMode(true);
        process.stdin.resume();
        process.stdin.setEncoding("utf8");
        process.stdin.on("data", (key) => {
          if (key === "n") {
            triggerNextModel();
            console.log("\n\x1b[33m→ forced model switch on next request\x1b[0m");
          } else if (key === "\u0003") {
            process.exit(0); // Ctrl+C
          }
        });
      }
      const { SwitcherServer } = await import("../src/server.js");
      const server = new SwitcherServer();
      await server.listen({ host, port });
      const shutdown = async () => {
        if (process.stdin.isTTY) process.stdin.setRawMode(false);
        await server.close();
        process.exit(0);
      };
      process.on("SIGINT", shutdown);
      process.on("SIGTERM", shutdown);
      break;
    }

    case "config": {
      printHeader();
      const config = overrideConfig(args);
      const scope = await chooseScope(loadSettings(), args.scope);
      saveSettings({ scope });
      const credRegistry = credentialedRegistry(registry);
      await writeConfig({ scope, registry: credRegistry, config });
      break;
    }

    case "detect": {
      printHeader();
      printDiscovery(registry);
      const models = discoverModels(registry);
      console.log(`\nUsable models (${models.length}):`);
      for (const m of models) console.log(`  ${m.id.padEnd(48)} ctx=${m.context} provider=${m.provider}`);
      const summary = opencodeAuthSummary();
      const entries = Object.entries(summary);
      if (entries.length) {
        console.log("\nOpenCode auth store:");
        for (const [provider, info] of entries) {
          const kind = `${info.type}${info.expires ? ` (${info.expires})` : ""}${info.hasKey ? " key" : ""}${info.hasAccess ? " oauth" : ""}`;
          console.log(`  ${provider}: ${kind}`);
        }
      }
      break;
    }

    case "next": {
      printHeader();
      triggerNextModel();
      console.log("triggered model switch for next request\n");
      break;
    }

    case "models": {
      printHeader();
      const autoCandidates = registry.autoCandidates({
        autoPool: loadConfig().autoPool,
        allowPaidModelsInAuto: loadConfig().allowPaidModelsInAuto === true,
      });
      console.log(`AUTO candidates (${autoCandidates.length}):`);
      for (const m of autoCandidates) console.log(`  ${m.id.padEnd(50)} ctx=${m.context} provider=${m.provider}`);
      console.log("");
      console.log(`All selectable (${registry.selectableModels().length}):`);
      for (const m of registry.selectableModels()) console.log(`  ${m.id}`);
      break;
    }

    case "file": {
      console.log(`credentials: ${switchrHome()}\\credentials.json`);
      console.log(`settings:    ${switchrHome()}\\settings.json`);
      const creds = loadCredentials();
      console.log(`stored providers: ${Object.keys(creds).map((k) => `${k}=${maskKey(creds[k])}`).join(", ") || "(none)"}`);
      break;
    }

    default:
      die(`unknown command "${command}". run \`switchr help\`.`);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import http from "node:http";
import { Readable } from "node:stream";
import { loadConfig } from "./config.js";
import { loadRegistry } from "./registry.js";
import { HealthStore } from "./health.js";
import { Router, VIRTUAL_MODEL_ID } from "./router.js";
import { createLogger } from "./logger.js";
import { resolveProviderCredentials, opencodeAuthSummary } from "./auth.js";

const VIRTUAL_MODEL_ENTRY = {
  id: VIRTUAL_MODEL_ID,
  object: "model",
  created: 1_750_000_000,
  owned_by: "auto-model-switcher",
  name: "auto (automatic failover)",
  description: "Automatically selects the best available model and fails over across providers on rate limits, quota, 5xx, timeouts and context-length errors.",
};

export class SwitcherServer {
  constructor(opts = {}) {
    this.config = opts.config ?? loadConfig();
    this.log = opts.log ?? createLogger({ level: this.config.logLevel, logFile: this.config.logFile });
    this.registry = opts.registry ?? loadRegistry();
    this.health = opts.health ?? new HealthStore({
      stateFile: this.config.stateFile,
      cooldownsSeconds: this.config.cooldownsSeconds,
      contextOverrideSeconds: this.config.cooldownContextOverrideSeconds,
    });
    this.auth = {
      resolve: (provider) => resolveProviderCredentials(provider),
      describe: (provider) => resolveProviderCredentials(provider).source || "none",
    };
    this.router = opts.router ?? new Router({
      registry: this.registry,
      health: this.health,
      auth: this.auth,
      config: this.config,
      log: this.log,
    });
    this.server = null;
  }

  createServer() {
    this.server = http.createServer((req, res) => this._onRequest(req, res));
    this.server.requestTimeout = this.config.requestTimeoutMs || 180_000;
    this.server.headersTimeout = 30_000;
    return this.server;
  }

  listen({ host = this.config.host, port = this.config.port } = {}) {
    if (!this.server) this.createServer();
    return new Promise((resolve, reject) => {
      this.server.once("error", reject);
      this.server.listen(port, host, () => {
        this.log?.info(`switcher listening on http://${host}:${port}`);
        resolve(this.server);
      });
    });
  }

  close() {
    return new Promise((resolve) => {
      if (!this.server) return resolve();
      try {
        this.server.closeAllConnections?.();
      } catch {
        /* ignore */
      }
      this.server.close(() => {
        this.health.close();
        this.log?.info("switcher stopped");
        this.log.close?.();
        resolve();
      });
      // safety: never hang shutdown on a lingering connection
      setTimeout(() => resolve(), 500).unref?.();
    });
  }

  async _onRequest(req, res) {
    const started = Date.now();
    const requestId = `req-${Math.random().toString(36).slice(2, 10)}`;
    res.setHeader("access-control-allow-origin", "*");
    res.setHeader("access-control-allow-headers", "authorization, content-type, x-api-key, x-request-id");
    res.setHeader("access-control-allow-methods", "GET, POST, OPTIONS");
    res.setHeader("access-control-expose-headers", "x-model-used, x-request-id, x-failover-count, x-context-compacted, retry-after");
    res.setHeader("x-request-id", requestId);

    if (req.method === "OPTIONS") {
      res.writeHead(204);
      res.end();
      return;
    }

    if (this.config.apiKey && !this._authorized(req)) {
      this.log?.warn(`[${requestId}] unauthorized request ${req.method} ${req.url}`);
      this._json(res, 401, { error: { message: "invalid or missing API key", type: "auth_error", code: "invalid_api_key" } });
      return;
    }

    const url = (req.url || "").split("?")[0];
    const isChat = url.endsWith("/chat/completions") || url === "/v1/chat/completions";
    const isModels = url.endsWith("/models") || url === "/v1/models";
    const isHealth = url === "/healthz" || url === "/health";
    const isRoot = url === "/" || url === "/v1";

    try {
      if (req.method === "GET" && isHealth) return this._handleHealth(req, res);
      if (req.method === "GET" && isModels) return this._handleModels(req, res);
      if (req.method === "GET" && isRoot) return this._handleRoot(req, res);
      if (req.method === "POST" && isChat) return await this._handleChat(req, res, requestId);

      this._json(res, 404, { error: { message: `not found: ${req.method} ${url}`, type: "not_found_error", code: "not_found" } });
    } catch (err) {
      this.log?.error(`[${requestId}] unhandled error: ${err.stack || err.message}`);
      if (!res.headersSent) this._json(res, 500, { error: { message: "internal server error", type: "server_error" } });
      else res.end();
    } finally {
      this.log?.debug(`[${requestId}] ${req.method} ${url} -> ${res.statusCode} ${Date.now() - started}ms`);
    }
  }

  _authorized(req) {
    const expected = `Bearer ${this.config.apiKey}`;
    const header = req.headers.authorization || "";
    const xkey = req.headers["x-api-key"] || "";
    return header === expected || xkey === this.config.apiKey;
  }

  async _handleChat(req, res, requestId) {
    const bodyText = await this._readBody(req);
    if (bodyText === null) {
      return this._json(res, 413, { error: { message: "request body too large", type: "payload_too_large", code: "body_too_large" } });
    }
    let body;
    try {
      body = bodyText ? JSON.parse(bodyText) : {};
    } catch {
      return this._json(res, 400, { error: { message: "invalid JSON body", type: "invalid_request_error", code: "invalid_json" } });
    }
    if (!body || typeof body !== "object") {
      return this._json(res, 400, { error: { message: "body must be a JSON object", type: "invalid_request_error" } });
    }

    const result = await this.router.handle(body, { requestId });
    if (result.usedModel) res.setHeader("x-model-used", result.usedModel);
    if (result.failoverLog?.length) res.setHeader("x-failover-count", String(result.failoverLog.length));
    if (result.contextCompacted) res.setHeader("x-context-compacted", "true");

    if (result.ok && result.stream) {
      // passthrough SSE/JSON stream from the winning provider
      const contentType = result.headers?.get?.("content-type") || (body.stream ? "text/event-stream" : "application/json");
      res.writeHead(200, {
        "content-type": contentType,
        "cache-control": "no-cache",
        "x-accel-buffering": "no",
      });
      // flush headers now: with a slow or still-opening upstream we don't want
      // the client waiting for the first byte before the 200 appears
      res.flushHeaders?.();
      await streamResponse(res, result.stream);
      return;
    }

    if (result.ok) {
      return this._json(res, 200, result.body ?? { id: requestId, object: "chat.completion", created: Math.floor(Date.now() / 1000), model: result.usedModel, choices: [], usage: {} });
    }

    const status = result.status || 502;
    const payload = result.body || { error: { message: `upstream error (${status})`, type: "upstream_error" } };
    if (result.headers?.get?.("retry-after")) res.setHeader("retry-after", result.headers.get("retry-after"));
    this._json(res, status, payload);
  }

  _handleModels(req, res) {
    const models = this.registry.selectableModels().map((m) => ({
      id: m.id,
      object: "model",
      created: Math.floor((m.created ?? 1_750_000_000)),
      owned_by: m.provider,
      name: m.name,
      ...(m.description ? { description: m.description } : {}),
    }));
    models.unshift(VIRTUAL_MODEL_ENTRY);
    this._json(res, 200, { object: "list", data: models });
  }

  _handleHealth(req, res) {
    const models = this.registry.allModels();
    const autoCandidates = this.registry.autoCandidates({
      autoPool: this.config.autoPool,
      allowPaidModelsInAuto: this.config.allowPaidModelsInAuto === true,
      excluded: this.config.excludedModels,
      preferred: this.config.preferredModels,
    });
    const providers = Object.entries(this.registry.raw.providers || {}).map(([id, p]) => ({
      id,
      name: p.name || id,
      credentials: this.auth.describe({ id, ...p }),
    }));
    const health = this.health.snapshot();
    this._json(res, 200, {
      ok: true,
      version: "1.0.0",
      providers,
      modelCount: models.length,
      autoCandidateCount: autoCandidates.length,
      autoCandidates: autoCandidates.map((m) => m.id),
      cooldowns: health,
      opencodeAuth: opencodeAuthSummary(),
      timestamp: new Date().toISOString(),
    });
  }

  _handleRoot(req, res) {
    this._json(res, 200, {
      name: "opencode auto-model-switcher",
      version: "1.0.0",
      endpoints: ["POST /v1/chat/completions", "GET /v1/models", "GET /healthz"],
      virtualModel: VIRTUAL_MODEL_ID,
    });
  }

  _readBody(req) {
    return new Promise((resolve) => {
      const limit = 20 * 1024 * 1024; // 20 MB
      const chunks = [];
      let size = 0;
      let done = false;
      req.on("data", (c) => {
        if (done) return;
        size += c.length;
        if (size > limit) {
          done = true;
          req.destroy();
          resolve(null);
          return;
        }
        chunks.push(c);
      });
      req.on("end", () => {
        if (done) return;
        resolve(Buffer.concat(chunks).toString("utf8"));
      });
      req.on("error", () => resolve(null));
    });
  }

  _json(res, status, payload) {
    const text = JSON.stringify(payload);
    res.writeHead(status, {
      "content-type": "application/json; charset=utf-8",
      "content-length": Buffer.byteLength(text),
    });
    res.end(text);
  }
}

async function streamResponse(res, webStream) {
  let reader = null;
  // Client went away mid-stream: abort the upstream. The stream is locked by
  // the reader once pumping starts, so cancel via the reader (the correct API);
  // ReadableStream#cancel() on a locked stream returns a rejected promise,
  // which would otherwise surface as an unhandled rejection and crash Node.
  const cancelUpstream = () => {
    try {
      if (reader) reader.cancel("client disconnected").catch(() => {});
      else if (webStream?.getReader) webStream.cancel("client disconnected").catch(() => {});
      else if (webStream?.destroy) webStream.destroy();
    } catch {
      /* ignore */
    }
  };
  res.on("close", cancelUpstream);
  res.on("error", () => {});
  try {
    // web ReadableStream (e.g. fetch response.body) - track the reader so we can
    // cancel it on disconnect. Do NOT rely on Symbol.asyncIterator: Node web
    // streams have one too, but then the stream is locked by an internal reader
    // and webStream.cancel() would throw ERR_INVALID_STATE.
    if (typeof webStream.getReader === "function") {
      reader = webStream.getReader();
      const pump = () => {
        return reader.read().then(({ done, value }) => {
          if (done) {
            res.end();
            return;
          }
          if (!res.write(Buffer.from(value))) {
            return new Promise((r) => res.once("drain", () => pump().then(r)));
          }
          return pump();
        }).catch(() => res.end());
      };
      await pump();
      return;
    }
    // genuine Node stream (no getReader)
    for await (const chunk of webStream) res.write(chunk);
    res.end();
  } catch (err) {
    try {
      res.end();
    } catch {
      /* ignore */
    }
  }
}

// ---- CLI entry -------------------------------------------------------------

const isMain = process.argv[1] && process.argv[1].endsWith("server.js");
if (isMain) {
  const server = new SwitcherServer();
  server
    .listen()
    .then(() => {
      const shutdown = () => {
        server.close().then(() => process.exit(0));
        setTimeout(() => process.exit(0), 2000).unref?.();
      };
      process.on("SIGINT", shutdown);
      process.on("SIGTERM", shutdown);
    })
    .catch((err) => {
      // eslint-disable-next-line no-console
      console.error("failed to start:", err.message);
      process.exit(1);
    });
}

export { Readable, VIRTUAL_MODEL_ENTRY };
